#[derive(Debug, Clone, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    host: String,
    port: String,
    path: String,
}

impl URL {
    pub fn new(input: &str) -> Self {
        if let Some(scheme_end) = input.find("://") {
            let scheme = &input[..scheme_end];
            let remainder = &input[scheme_end + 3..];
            let authority_end = remainder
                .find(|ch| matches!(ch, '/' | '?' | '#'))
                .unwrap_or(remainder.len());
            let authority = &remainder[..authority_end];
            let path = strip_query_and_fragment(&remainder[authority_end..]);
            let host_port = authority.rsplit_once('@').map_or(authority, |(_, tail)| tail);

            let (host, port) = if let Some(port_start) = host_port.find(':') {
                (&host_port[..port_start], &host_port[port_start + 1..])
            } else {
                (host_port, "")
            };

            Self {
                scheme: scheme.to_string(),
                host: host.to_string(),
                port: port.to_string(),
                path: path.to_string(),
            }
        } else {
            Self {
                scheme: String::new(),
                host: String::new(),
                port: String::new(),
                path: strip_query_and_fragment(input).to_string(),
            }
        }
    }

    pub fn is_valid_url(input: &str) -> bool {
        let parsed = Self::new(input);
        !parsed.host.is_empty() || !parsed.path.is_empty()
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> &str {
        &self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn scheme_is_valid(&self) -> bool {
        validation::is_scheme_valid(self.scheme())
    }

    pub fn host_is_valid(&self) -> bool {
        validation::is_host_valid(self.host())
    }

    pub fn port_is_valid(&self) -> bool {
        validation::is_port_valid(self.port())
    }
}

fn strip_query_and_fragment(input: &str) -> &str {
    let end = input
        .find(|ch| matches!(ch, '?' | '#'))
        .unwrap_or(input.len());
    &input[..end]
}
pub fn split_path(path: &str) -> Vec<String> {
    path.split('/')
        .filter(|segment| !segment.is_empty())
        .map(str::to_string)
        .collect()
}
pub fn is_scheme_valid(scheme: &str) -> bool {
    let mut chars = scheme.chars();
    match chars.next() {
        Some(first) if first.is_ascii_alphabetic() => {}
        _ => return false,
    }

    chars.all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '+' | '-' | '.'))
}

pub fn is_host_valid(host: &str) -> bool {
    !host.is_empty()
        && host
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '[' | ']'))
}

pub fn is_port_valid(port: &str) -> bool {
    match parse_port_prefix(port) {
        Some(value) => (0..=65_535).contains(&value),
        None => false,
    }
}

fn parse_port_prefix(port: &str) -> Option<i64> {
    let trimmed = port.trim_start_matches(char::is_whitespace);
    if trimmed.is_empty() {
        return None;
    }

    let bytes = trimmed.as_bytes();
    let mut index = 0usize;
    let mut sign = 1i64;

    match bytes.first().copied() {
        Some(b'+') => index = 1,
        Some(b'-') => {
            sign = -1;
            index = 1;
        }
        _ => {}
    }

    let mut value = 0i64;
    let mut saw_digit = false;

    while let Some(&byte) = bytes.get(index) {
        if !byte.is_ascii_digit() {
            break;
        }
        saw_digit = true;
        value = value.checked_mul(10)?.checked_add((byte - b'0') as i64)?;
        index += 1;
    }

    if !saw_digit {
        return None;
    }

    Some(sign * value)
}

