fn parse_url(input: &str) -> URL {
    if let Some(scheme_end) = input.find("://") {
        let scheme = input[..scheme_end].to_string();
        let rest = &input[scheme_end + 3..];
        let authority_end = rest
            .find(|ch| matches!(ch, '/' | '?' | '#'))
            .unwrap_or(rest.len());
        let authority = &rest[..authority_end];

        let path = if authority_end < rest.len() && rest.as_bytes()[authority_end] == b'/' {
            strip_query_and_fragment(&rest[authority_end..]).to_string()
        } else {
            String::new()
        };

        let host_port = authority
            .rsplit_once('@')
            .map(|(_, host_port)| host_port)
            .unwrap_or(authority);

        let colon_count = host_port.bytes().filter(|byte| *byte == b':').count();
        let (host, port) = if colon_count == 1 {
            match host_port.split_once(':') {
                Some((host, port)) => (host.to_string(), port.to_string()),
                None => (host_port.to_string(), String::new()),
            }
        } else {
            (host_port.to_string(), String::new())
        };

        URL {
            scheme,
            host,
            port,
            path,
        }
    } else {
        URL {
            scheme: String::new(),
            host: String::new(),
            port: String::new(),
            path: strip_query_and_fragment(input).to_string(),
        }
    }
}

fn strip_query_and_fragment(input: &str) -> &str {
    let end = input
        .find(|ch| matches!(ch, '?' | '#'))
        .unwrap_or(input.len());
    &input[..end]
}
pub fn is_scheme_valid(scheme: &str) -> bool {
    let mut chars = scheme.chars();

    match chars.next() {
        Some(ch) if ch.is_ascii_alphabetic() => {}
        _ => return false,
    }

    chars.all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '+' | '-' | '.'))
}

pub fn is_host_valid(host: &str) -> bool {
    !host.is_empty()
        && host.chars().all(|ch| {
            ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | ':' | '[' | ']')
        })
}

pub fn is_port_valid(port: &str) -> bool {
    let port_number = match parse_stoi_like(port) {
        Some(value) => value,
        None => return false,
    };

    (0..=65535).contains(&port_number)
}

fn parse_stoi_like(input: &str) -> Option<i64> {
    let trimmed = input.trim_start_matches(|ch: char| ch.is_whitespace());
    if trimmed.is_empty() {
        return None;
    }

    let bytes = trimmed.as_bytes();
    let mut index = 0usize;
    let mut sign = 1i64;

    if bytes[index] == b'+' {
        index += 1;
    } else if bytes[index] == b'-' {
        sign = -1;
        index += 1;
    }

    let mut value = 0i64;
    let mut saw_digit = false;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        saw_digit = true;
        value = value.checked_mul(10)?;
        value = value.checked_add((bytes[index] - b'0') as i64)?;
        index += 1;
    }

    if !saw_digit {
        return None;
    }

    value.checked_mul(sign)
}
pub fn split_path(path: &str) -> Vec<String> {
    path.split('/')
        .filter(|segment| !segment.is_empty())
        .map(str::to_string)
        .collect()
}

